"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8734],{78064:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"EmoteController","desc":"Plays the equipped emote from the lobby: B on keyboard, a touch button on\\nmobile. The action is bound only while the player is in the lobby (their\\ncharacter has no `RoundTag`, which every round spawn stamps) and has an\\nemote equipped. Pressing again or moving stops it.\\n\\nClient-side on purpose: animations the owner plays on their own Animator\\nreplicate to everyone, and an exploiter can already play any animation on\\ntheir own character, so a server round trip would guard nothing.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Client"],"source":{"line":17,"path":"src/Client/Features/Market/Controllers/EmoteController.luau"}}')}}]);